<?php
require_once __DIR__ . '/config.php'; require_login();$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$product=(int)($_POST['product_id']??0);$type=(string)($_POST['type']??'');$qty=(int)($_POST['quantity']??0);$note=trim((string)($_POST['note']??''));if(!$product||!in_array($type,['in','out'],true)||$qty<1)flash('Pilih produk, jenis transaksi, dan jumlah minimal 1.','error');else try{$pdo->beginTransaction();$s=$pdo->prepare('SELECT id,quantity FROM products WHERE id=? FOR UPDATE');$s->execute([$product]);$p=$s->fetch();if(!$p)throw new RuntimeException('Produk tidak ditemukan.');if($type==='out'&&(int)$p['quantity']<$qty)throw new RuntimeException('Stok tidak cukup untuk transaksi keluar.');$delta=$type==='in'?$qty:-$qty;$pdo->prepare('UPDATE products SET quantity=quantity+? WHERE id=?')->execute([$delta,$product]);$pdo->prepare('INSERT INTO stock_transactions(product_id,user_id,type,quantity,note) VALUES(?,?,?,?,?)')->execute([$product,current_user()['id'],$type,$qty,$note?:null]);$pdo->commit();flash('Transaksi berhasil dicatat dan stok diperbarui.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash($e instanceof RuntimeException?$e->getMessage():'Transaksi gagal diproses.','error');}redirect('transactions.php');}
$products=$pdo->query('SELECT id,sku,name,quantity,unit FROM products ORDER BY name')->fetchAll();$pageTitle='Transaksi stok';require 'partials_header.php';?>
<section class="panel"><div class="panel-heading"><h2>Catat barang masuk / keluar</h2></div><p class="muted">Setiap transaksi otomatis memperbarui stok dan tercatat di histori.</p><form method="post" class="form-grid"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><div class="wide"><label>Produk *</label><select name="product_id" required><option value="">Pilih produk</option><?php foreach($products as $p): ?><option value="<?= $p['id'] ?>"><?= e($p['sku'].' — '.$p['name'].' (stok: '.$p['quantity'].' '.$p['unit'].')') ?></option><?php endforeach; ?></select></div><div><label>Jenis transaksi *</label><select name="type" required><option value="in">Barang masuk</option><option value="out">Barang keluar</option></select></div><div><label>Jumlah *</label><input type="number" name="quantity" min="1" required></div><div class="wide"><label>Catatan</label><textarea name="note" rows="2" maxlength="255" placeholder="Contoh: pembelian PO-001 / pemakaian produksi"></textarea></div><div class="wide"><button class="btn primary">Simpan transaksi</button></div></form></section>
<section class="panel"><div class="panel-heading"><h2>Petunjuk</h2></div><ul class="help-list"><li><strong>Barang masuk:</strong> menambah jumlah stok.</li><li><strong>Barang keluar:</strong> mengurangi stok; sistem menolak jika stok tidak mencukupi.</li><li><strong>Histori:</strong> buka menu Histori untuk mencari, memfilter, mengurutkan, dan mengekspor laporan CSV.</li></ul></section><?php require 'partials_footer.php'; ?>
